#include "strata/core/service_events.hpp"
#include <chrono>
#include <cstdio>
#include <stdexcept>

// No queue/context/device creation or enqueue: exercise host bookkeeping under ASan/UBSan.
int main() {
    using namespace strata::core;
    if (!service_events_requested()) return 2;
    ServiceEvents ledger;
    ServiceMeta meta;
    meta.kind = "host_fixture";
    const ServiceClock::time_point before{};
    const auto after = before + std::chrono::nanoseconds(1);
    const sycl::event no_command;
    ledger.begin();
    bool refused = false;
    try { ledger.begin(); }
    catch (const std::runtime_error&) { refused = true; }
    if (!refused) return 1;
    for (size_t i = 0; i <= ServiceEvents::cap; ++i) ledger.record(no_command, meta, before, after);
    ledger.finish(false);  // Cap and abandoned scope: must query no event.
    ledger.begin();
    ledger.record(no_command, meta, before, after);
    ledger.finish(true);  // A default event has no profiled queue: must remain incomplete.
    ledger.begin();
    ledger.record(no_command, meta, after, before);
    ledger.finish(false);  // Invalid host clock must not silently become a valid zero duration.
    { ServiceScope scope(ledger); }  // RAII abandonment: no event query and no cumulative prior counts.
    { ServiceScope scope(ledger); scope.complete(); }
    std::puts("HOST_SERVICE_FIXTURE status=PASS overlap_refused=1 cap_submissions=200001 scopes=5 no_gpu_enqueue=1");
    return 0;
}
